// Prints the funding (unshielded) address for the Preprod wallet
// generated by generate-preprod-wallet.mjs. Public information — safe to
// print, paste into the faucet, or share. Does NOT print the mnemonic.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { WebSocket } from "ws";
globalThis.WebSocket = WebSocket;

import { FluentWalletBuilder } from "@midnight-ntwrk/testkit-js";
import { LedgerParameters } from "@midnight-ntwrk/midnight-js-protocol/ledger";

const envPath = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", ".env.preprod");
const raw = readFileSync(envPath, "utf8");
const mnemonic = raw.match(/PREPROD_MNEMONIC="([^"]+)"/)[1];

const preprodEnvConfig = {
  walletNetworkId: "preprod",
  networkId: "preprod",
  indexer: "https://indexer.preprod.midnight.network/api/v4/graphql",
  indexerWS: "wss://indexer.preprod.midnight.network/api/v4/graphql/ws",
  node: "https://rpc.preprod.midnight.network",
  nodeWS: "wss://rpc.preprod.midnight.network",
  proofServer: "http://127.0.0.1:16300",
  faucet: "https://midnight-tmnight-preprod.nethermind.dev/"
};

const dustOptions = {
  ledgerParams: LedgerParameters.initialParameters(),
  additionalFeeOverhead: 1_000n,
  feeBlocksMargin: 5
};

const builder = FluentWalletBuilder.forEnvironment(preprodEnvConfig).withDustOptions(dustOptions);
const { keystore } = await builder.withMnemonic(mnemonic).buildWithoutStarting();

console.log("Unshielded funding address (paste into the Preprod faucet):");
console.log(String(keystore.getBech32Address()));
process.exit(0);
